import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";
import styled from "styled-components";

const FuelPage = () => {
    const { id } = useParams(); // Fetching lorry_id from the URL params
    const [fuelRecords, setFuelRecords] = useState([]);
    const [newFuel, setNewFuel] = useState({
        fill_date: "",
        bunk_name: "",
        total_amount: "",
        amount_paid: ""
    });

    useEffect(() => {
        // Fetch fuel records for the specific lorry
        const fetchFuelRecords = async () => {
            try {
                const response = await axios.get(`http://localhost:5001/api/fuel/${id}`);
                setFuelRecords(response.data);
            } catch (error) {
                console.error("Error fetching fuel records:", error);
            }
        };
        fetchFuelRecords();
    }, [id]);

    // Handle form input changes
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setNewFuel({ ...newFuel, [name]: value });
    };

    // Handle fuel record submission
    const handleAddFuel = async (e) => {
        e.preventDefault();
        try {
            await axios.post("http://localhost:5001/api/fuel/add", {
                lorry_id: id, // Auto-included lorry_id
                ...newFuel,
            });
            alert("Fuel record added successfully!");
            setNewFuel({ fill_date: "", bunk_name: "", total_amount: "", amount_paid: "" });
        } catch (error) {
            console.error("Error adding fuel data:", error);
        }
    };

    return (
        <Container>
            <h1>Fuel Records for Lorry ID: {id}</h1>
            <Form onSubmit={handleAddFuel}>
                <Input type="date" name="fill_date" value={newFuel.fill_date} onChange={handleInputChange} required />
                <Input type="text" name="bunk_name" placeholder="Bunk Name" value={newFuel.bunk_name} onChange={handleInputChange} required />
                <Input type="number" name="total_amount" placeholder="Total Amount" value={newFuel.total_amount} onChange={handleInputChange} required />
                <Input type="number" name="amount_paid" placeholder="Amount Paid" value={newFuel.amount_paid} onChange={handleInputChange} required />
                <Button type="submit">Add Fuel Record</Button>
            </Form>

            {/* Display Fuel Records */}
            <FuelList>
                {fuelRecords.length > 0 ? (
                    fuelRecords.map((record) => (
                        <FuelRecord key={record.id}>
                            <p><strong>Date:</strong> {record.fill_date}</p>
                            <p><strong>Bunk Name:</strong> {record.bunk_name}</p>
                            <p><strong>Total Amount:</strong> ₹{record.total_amount}</p>
                            <p><strong>Amount Paid:</strong> ₹{record.amount_paid}</p>
                        </FuelRecord>
                    ))
                ) : (
                    <p>No fuel records available.</p>
                )}
            </FuelList>
        </Container>
    );
};

// Styled Components for styling the Fuel Page
const Container = styled.div`
    padding: 20px;
    max-width: 600px;
    margin: auto;
    text-align: center;
`;

const Form = styled.form`
    display: flex;
    flex-direction: column;
    gap: 15px;
    margin-bottom: 20px;
`;

const Input = styled.input`
    padding: 10px;
    border: 1px solid #ccc;
    border-radius: 5px;
`;

const Button = styled.button`
    padding: 10px;
    background-color: #28a745;
    color: white;
    border: none;
    border-radius: 5px;
    cursor: pointer;

    &:hover {
        background-color: #218838;
    }
`;

const FuelList = styled.div`
    margin-top: 20px;
    border-top: 1px solid #ccc;
    padding-top: 20px;
`;

const FuelRecord = styled.div`
    border: 1px solid #ddd;
    padding: 15px;
    margin-bottom: 10px;
    border-radius: 5px;
    text-align: left;
    background: #f9f9f9;
`;

export default FuelPage;
